// Genuary #04 : Black on black


#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))

float box (vec3 p, vec3 c)
{
    vec3 q = abs(p)-c;
    return min(0., max(q.x, max(q.y, q.z)))+length(max(q, 0.));
}

float sc (vec3 p, float d)
{
    p = abs(p);
    p = max(p, p.yzx);
    return min(p.x, min(p.y, p.z)) - d;
}

float SDF (vec3 p)
{
    p.xy *= rot(iTime);
    p.yz *= rot(-iTime);
    float d = max(-sc(p, .15), box(p, vec3(.2))); 

    float circ = length(p)-(.15 + exp(-fract(iTime*5.))*.025); 
    d = min(d, circ);

    return d;
}

vec3 gn (vec3 p)
{
    vec2 eps = vec2(0.01, 0.);
    return normalize(SDF(p)-vec3(SDF(p-eps.xyy),SDF(p-eps.yxy),SDF(p-eps.yyx)));
}

float spec (vec3 rd, vec3 l, vec3 n)
{return pow(max(dot(n, normalize(l-rd)), 0.), 8.);}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;

    vec3 ro = vec3(0.01, 0.01, -.5), rd=normalize(vec3(uv, 1.)), p=ro,
    col=vec3(0.), l=normalize(vec3(1.5, 2.5, .1));   
    bool hit = false;

    for (float i=0.; i<32. ; i++)
    {
        float d= SDF(p);
        if (d<0.001)
        {
            hit = true;
            vec3 n = gn(p);
            rd = mix(normalize(reflect(rd, n)), rd, pow(clamp(1.-dot(-rd, n), 0., 1.), .8) ) ;
            p *= sign(p);
            break;
        }
        p += d*rd;
    }    
    if (hit)
    {    vec3 n = gn(p);
        col = vec3(spec(rd, l, n));
    }

    fragColor = vec4(sqrt(col),1.0);
}
